begin;
select plan(14);
select is((select array_agg(attname||':'||format_type(atttypid,atttypmod)||':'||attnotnull order by attnum) from pg_attribute where attrelid='workspace_private.workspace_context'::regclass and attnum>0 and not attisdropped),array['id:uuid:true','session_id:uuid:true','user_id:uuid:true','organization_id:uuid:true','membership_revision:bigint:true','entitlement_revision:bigint:true','context_revision:bigint:true','fixed_expires_at:timestamp with time zone:true','revoked_at:timestamp with time zone:false']::text[],'context table has the exact session-bound shape');
select ok((select count(*)=1 from pg_constraint where conrelid='workspace_private.workspace_context'::regclass and contype='u' and pg_get_constraintdef(oid)='UNIQUE (session_id)'),'session_id is uniquely constrained');
select ok((select count(*)=1 from pg_constraint where conrelid='workspace_private.workspace_context'::regclass and contype='f' and pg_get_constraintdef(oid) like 'FOREIGN KEY (organization_id) REFERENCES workspace_private.organization(id)%'),'context references its organization');
select ok((select count(*)=1 from pg_constraint where conrelid='workspace_private.workspace_context'::regclass and contype='f' and pg_get_constraintdef(oid) like 'FOREIGN KEY (organization_id, user_id) REFERENCES workspace_private.organization_membership(organization_id, user_id)%'),'context references its user membership');
select ok((select count(*)=3 and bool_and(pg_get_constraintdef(oid) like any(array['%membership_revision > 0%','%entitlement_revision >= 0%','%context_revision > 0%'])) from pg_constraint where conrelid='workspace_private.workspace_context'::regclass and contype='c'),'context revisions are bounded');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='workspace_private.workspace_context'::regclass) and (select count(*)=1 and bool_and(cmd='ALL' and roles=array['workspace_context_owner']::name[] and qual='true' and with_check='true') from pg_policies where schemaname='workspace_private' and tablename='workspace_context'),'context has forced RLS with one owner policy');
select ok(not has_table_privilege('anon','workspace_private.workspace_context','SELECT,INSERT,UPDATE,DELETE') and not has_table_privilege('authenticated','workspace_private.workspace_context','SELECT,INSERT,UPDATE,DELETE') and not has_table_privilege('service_role','workspace_private.workspace_context','SELECT,INSERT,UPDATE,DELETE'),'boundary roles have no context table ACL');
select ok(has_schema_privilege('authenticated','workspace_api','USAGE') and has_function_privilege('authenticated','workspace_api.invalidate_workspace_context()','EXECUTE'),'authenticated can reach the invalidation RPC');
select ok(not has_schema_privilege('anon','workspace_api','USAGE') and not has_schema_privilege('service_role','workspace_api','USAGE') and not has_function_privilege('anon','workspace_api.invalidate_workspace_context()','EXECUTE') and not has_function_privilege('service_role','workspace_api.invalidate_workspace_context()','EXECUTE'),'anon and service_role cannot reach the invalidation RPC');
select ok((select proowner='workspace_context_owner'::regrole and prosecdef and proconfig=array['search_path=pg_catalog, workspace_private, pg_temp']::text[] from pg_proc where oid='workspace_api.invalidate_workspace_context()'::regprocedure),'RPC has the isolated owner and fixed definer search path');
select ok((select strpos(definition,'current_setting')>0 and strpos(definition,'current_setting')<strpos(definition,'from workspace_private.workspace_context') from (select pg_get_functiondef('workspace_api.invalidate_workspace_context()'::regprocedure) definition) f),'claims are captured before context access');
select ok((select definition like '%jsonb_typeof(claims)%' and definition like '%expires<>trunc(expires)%' and definition like '%to_timestamp(expires::bigint)<=statement_timestamp()%' and strpos(definition,'VOT02')<strpos(definition,'select * into context_row') and strpos(definition,'VOT03')>strpos(definition,'select * into context_row') and definition like '%context_row.revoked_at is not null%' from (select pg_get_functiondef('workspace_api.invalidate_workspace_context()'::regprocedure) definition) f),'RPC definition validates claims before session mutation and is repeat-safe');
select ok(has_table_privilege('workspace_context_owner','workspace_private.workspace_audit_event','INSERT') and not has_table_privilege('workspace_context_owner','workspace_private.workspace_audit_event','SELECT,UPDATE,DELETE') and (select count(*)=1 and bool_and(cmd='INSERT' and roles=array['workspace_context_owner']::name[] and with_check like '%organization_user%') from pg_policies where schemaname='workspace_private' and tablename='workspace_audit_event' and policyname='workspace_context_owner_audit_insert'),'audit access is insert-only and policy-bound');
select is((select array_agg(relname order by relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='workspace_private' and relname=any(array['organization','organization_membership','workspace_audit_event','workspace_context'])),array['organization','organization_membership','workspace_audit_event','workspace_context']::name[],'context migration preserves the required parent-object inventory');
select * from finish();
rollback;
